INSERT INTO "public"."combination_warnings" ("rule_id", "ingredient1", "ingredient2", "severity", "title", "message", "created_at") VALUES
  ('WARN-001', 'ING-001', 'ING-002', 'High', 'Severe Barrier Risk', 'BAHAYA: Mencampur BHA (Salicylic Acid) dan Retinol dapat menyebabkan iritasi parah, kemerahan, dan mengelupas. Pisahkan penggunaannya (BHA Pagi / Retinol Malam).', '2026-05-14 20:40:05.716362+00'),
  ('WARN-002', 'ING-004', 'ING-002', 'Medium', 'pH Imbalance & Irritation', 'PERINGATAN: Vitamin C dan Retinol bekerja di tingkat pH yang berbeda dan sangat mengiritasi jika digabung. Gunakan Vitamin C di pagi hari dan Retinol di malam hari.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-003', 'ING-001', 'ING-004', 'High', 'Acid Overload', 'BAHAYA: Menggunakan BHA bersamaan dengan Vitamin C (Ascorbic Acid) sangat rentan memicu iritasi dan rasa terbakar pada kulit karena keduanya bersifat asam.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-004', 'ING-011', 'ING-002', 'High', 'Severe Barrier Risk', 'BAHAYA: Glycolic Acid (AHA) adalah eksfoliator kuat. Melapisinya dengan Retinol akan menghancurkan skin barrier. Selang-seling penggunaan di malam yang berbeda.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-005', 'ING-012', 'ING-002', 'High', 'Severe Barrier Risk', 'BAHAYA: Lactic Acid (AHA) ditambah Retinol berisiko tinggi membuat kulit kering terkelupas dan sensitif terhadap cahaya matahari.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-006', 'ING-011', 'ING-001', 'Medium', 'Over-Exfoliation Risk', 'PERINGATAN: Menggabungkan AHA (Glycolic) dan BHA dapat menyebabkan over-eksfoliasi. Hanya gunakan jika kulitmu sangat toleran atau formulanya memang sudah dicampur dari pabrik.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-007', 'ING-078', 'ING-002', 'High', 'Ingredient Deactivation', 'BAHAYA: Benzoyl Peroxide dan Retinol akan saling membatalkan efektivitas satu sama lain (deaktivasi) sekaligus memicu kekeringan kulit yang ekstrem.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-008', 'ING-078', 'ING-004', 'High', 'Oxidation Warning', 'BAHAYA: Benzoyl Peroxide akan langsung mengoksidasi Vitamin C, membuatnya tidak berguna sama sekali untuk kulitmu.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-009', 'ING-078', 'ING-001', 'High', 'Extreme Dryness Risk', 'BAHAYA: BHA dan Benzoyl Peroxide adalah dua agen anti-jerawat yang sangat mengeringkan. Melapisinya dapat memicu inflamasi dan luka pada jerawat.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-010', 'ING-081', 'ING-004', 'High', 'Ingredient Deactivation', 'BAHAYA: Copper Peptides dan Vitamin C murni (Ascorbic Acid) tidak boleh digabung. Vitamin C akan memecah rantai peptida dan membuatnya tidak berfungsi.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-011', 'ING-081', 'ING-011', 'High', 'Peptide Breakdown', 'BAHAYA: Tingkat keasaman yang tinggi dari Glycolic Acid (AHA) akan merusak ikatan asam amino pada Copper Peptides.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-012', 'ING-081', 'ING-001', 'Medium', 'Peptide Breakdown', 'PERINGATAN: BHA dapat menurunkan pH kulit secara drastis, berisiko mengganggu kerja seluler dari Copper Peptides.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-013', 'ING-011', 'ING-004', 'High', 'Acid Overload', 'BAHAYA: Glycolic Acid dan Vitamin C sama-sama mengandalkan lingkungan pH rendah. Melapisinya dapat memicu rasa terbakar yang hebat, terutama pada kulit sensitif.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-014', 'ING-004', 'ING-003', 'Medium', 'Potential Niacin Flush', 'PERINGATAN: Meski banyak diperdebatkan, menggabungkan Vitamin C murni dan Niacinamide pada kulit yang sensitif dapat memicu kemerahan sementara (Niacin Flush).', '2026-05-14 20:40:05.716362+00'),
  ('WARN-015', 'ING-008', 'ING-002', 'High', 'Excessive Drying', 'BAHAYA: Produk dengan kandungan Alcohol Denat tinggi akan merusak lipid kulit, dan jika digabung dengan Retinol, akan menyebabkan iritasi parah.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-016', 'ING-008', 'ING-011', 'Medium', 'Barrier Disruption', 'PERINGATAN: AHA (Glycolic Acid) sudah mengelupas kulit mati. Menambahkan produk berbasis Alkohol tinggi akan menembus terlalu dalam dan memicu sensasi perih.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-017', 'ING-077', 'ING-011', 'Medium', 'Exfoliation Overload', 'PERINGATAN: Azelaic Acid memiliki sifat eksfoliasi ringan. Digabungkan dengan Glycolic Acid (AHA) bisa terlalu agresif untuk pemula.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-018', 'ING-077', 'ING-001', 'Medium', 'Exfoliation Overload', 'PERINGATAN: BHA dan Azelaic Acid sama-sama merawat pori-pori. Melapisinya bisa menyebabkan kulit terasa tertarik dan kering.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-019', 'ING-074', 'ING-011', 'Medium', 'High Irritation Potential', 'PERINGATAN: Kojic Acid (pencerah) dapat mengiritasi kulit. Melapisinya dengan AHA (Glycolic Acid) meningkatkan penyerapan Kojic Acid ke tingkat yang bisa memicu dermatitis kontak.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-020', 'ING-074', 'ING-002', 'Medium', 'High Irritation Potential', 'PERINGATAN: Retinol dan Kojic Acid sangat ampuh untuk hiperpigmentasi, tetapi melapisinya secara bersamaan berisiko tinggi menimbulkan peradangan.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-021', 'ING-028', 'ING-002', 'High', 'Surfactant Damage', 'BAHAYA: Menggunakan pembersih keras berbahan SLS (Sodium Lauryl Sulfate) sebelum mengoleskan Retinol akan memperparah efek samping Retinol secara eksponensial.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-022', 'ING-028', 'ING-011', 'High', 'Surfactant Damage', 'BAHAYA: Sabun cuci muka berbahan SLS mengikis minyak alami kulit. Diikuti dengan toner AHA, ini adalah resep pasti untuk merusak skin barrier.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-023', 'ING-078', 'ING-011', 'High', 'Chemical Burn Risk', 'BAHAYA: Benzoyl Peroxide digabungkan dengan Glycolic Acid sangat korosif pada kulit dan dapat memicu luka bakar kimiawi tingkat ringan.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-024', 'ING-078', 'ING-012', 'High', 'Chemical Burn Risk', 'BAHAYA: Benzoyl Peroxide dan Lactic Acid (AHA). Jangan pernah melapisinya kecuali atas anjuran langsung dari dokter kulit spesialis.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-025', 'ING-081', 'ING-002', 'Medium', 'Tolerability Issue', 'PERINGATAN: Meskipun tidak saling membatalkan, melapisi Copper Peptides dan Retinol bersamaan dapat memicu sensitivitas bagi kulit yang belum terbiasa.', '2026-05-14 20:40:05.716362+00'),
  ('WARN-026', 'ING-029', 'ING-001', 'Medium', 'Over-stripping Risk', 'PERINGATAN: Menggunakan pembersih dengan SLES (Sodium Laureth Sulfate) yang digabung dengan Salicylic Acid (BHA) dapat mengikis kelembapan alami kulit. Pastikan menggunakan pelembap setelahnya.', '2026-05-19 08:39:03.31852+00'),
  ('WARN-027', 'ING-127', 'ING-002', 'High', 'Severe Dryness', 'BAHAYA: Witch Hazel adalah astringent kuat. Menggabungkannya dalam rutinitas bersama Retinol dapat memicu kekeringan ekstrem dan rusaknya skin barrier.', '2026-05-19 08:39:03.31852+00'),
  ('WARN-028', 'ING-130', 'ING-011', 'High', 'Essential Oil & Acid Clash', 'BAHAYA: Peppermint Oil dapat mensensitisasi kulit. Menimpanya dengan Glycolic Acid (AHA) akan meningkatkan risiko iritasi, kemerahan, dan rasa terbakar.', '2026-05-19 08:39:03.31852+00'),
  ('WARN-029', 'ING-003', 'ING-012', 'Medium', 'pH Conflict', 'PERINGATAN: Niacinamide dan Lactic Acid (AHA) memiliki pH optimal yang berbeda. Penggunaan bersamaan dapat menyebabkan Niacinamide berubah menjadi Niacin, memicu kemerahan sementara (flushing).', '2026-05-19 08:39:03.31852+00'),
  ('WARN-030', 'ING-252', 'ING-004', 'High', 'Peptide Degradation', 'BAHAYA: Copper Tripeptide-1 akan rusak jika dicampur dengan Ascorbic Acid (Vitamin C murni).', '2026-05-19 08:39:26.132472+00'),
  ('WARN-031', 'ING-146', 'ING-011', 'Medium', 'Increased Sensitivity', 'PERINGATAN: Bakuchiol (alternatif retinol) jika dicampur dengan Glycolic Acid dapat meningkatkan sensitivitas kulit.', '2026-05-19 08:39:26.132472+00'),
  ('WARN-032', 'ING-003', 'ING-149', 'Low', 'Safe but monitor', 'INFO: Niacinamide dan Sodium Ascorbyl Phosphate aman digabung, namun pantau jika kulit Anda sangat sensitif.', '2026-05-19 08:39:26.132472+00'),
  ('WARN-034', 'ING-224', 'ING-225', 'Medium', 'Essential Oil Overload', 'PERINGATAN: Menggabungkan beberapa Essential Oils (Rosemary & Lavender) dapat memicu alergi pada kulit sensitif.', '2026-05-19 08:39:26.132472+00'),
  ('WARN-035', 'ING-078', 'ING-146', 'High', 'Irritation Risk', 'BAHAYA: Benzoyl Peroxide tidak disarankan digunakan bersama Bakuchiol karena memicu kekeringan ganda.', '2026-05-19 08:39:26.132472+00'),
  ('WARN-036', 'ING-013', 'ING-001', 'Medium', 'Double Acid', 'PERINGATAN: Mandelic Acid dan BHA bersifat eksfoliator. Gunakan bergantian agar tidak over-exfoliate.', '2026-05-19 08:39:26.132472+00'),
  ('WARN-039', 'ING-002', 'ING-014', 'Medium', 'Mild Exfoliation Clash', 'PERINGATAN: Meski PHA (Gluconolactone) lebih lembut, menggabungkannya dengan Retinol tetap bisa memicu iritasi pada kulit sensitif.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-040', 'ING-002', 'ING-077', 'Medium', 'Acid & Retinoid Overload', 'PERINGATAN: Azelaic Acid dan Retinol adalah kombinasi ampuh untuk jerawat namun sangat mengeringkan. Gunakan pelembap ekstra.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-041', 'ING-469', 'ING-011', 'High', 'Extreme Irritation', 'BAHAYA: Tretinoin tidak boleh digabung dengan Glycolic Acid. Ini akan menyebabkan luka bakar kimia ringan pada wajah.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-042', 'ING-469', 'ING-001', 'High', 'Extreme Dryness', 'BAHAYA: Tretinoin dan Salicylic Acid (BHA) bersamaan akan mematikan kelembapan kulit dan merusak skin barrier seketika.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-043', 'ING-468', 'ING-078', 'High', 'Prescription Clash', 'BAHAYA: Adapalene dan Benzoyl Peroxide (kecuali diformulasikan khusus seperti Epiduo) dapat menyebabkan pengelupasan ekstrem jika ditumpuk manual.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-046', 'ING-455', 'ING-011', 'High', 'Protein Denaturation', 'BAHAYA: EGF (sh-Oligopeptide-1) adalah protein. Menggabungkannya dengan Glycolic Acid (pH rendah) akan membuat EGF rusak dan tidak berguna.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-047', 'ING-455', 'ING-001', 'High', 'Protein Denaturation', 'BAHAYA: EGF dan Salicylic Acid memiliki konflik pH. BHA akan merusak struktur peptida EGF.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-048', 'ING-252', 'ING-011', 'High', 'Peptide Inactivation', 'BAHAYA: Asam kuat seperti Glycolic Acid merusak ikatan Copper Peptide, membuatnya menjadi oksidan yang merusak kulit.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-052', 'ING-465', 'ING-011', 'Medium', 'Retinyl & AHA', 'PERINGATAN: Retinyl Palmitate dengan AHA dapat mempercepat pergantian sel secara agresif. Waspadai tanda over-eksfoliasi.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-053', 'ING-078', 'ING-077', 'Medium', 'Overdrying Risk', 'PERINGATAN: Benzoyl Peroxide dan Azelaic Acid dapat menyebabkan kulit menjadi sangat kering dan bersisik.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-057', 'ING-028', 'ING-469', 'High', 'Severe Barrier Stripping', 'BAHAYA: SLS (Sodium Lauryl Sulfate) + Tretinoin akan menyebabkan kulit meradang, mengelupas, dan perih.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-058', 'ING-321', 'ING-001', 'Medium', 'Surfactant Interaction', 'PERINGATAN: Cocamide DEA dan Salicylic Acid bisa mengubah pH cleanser menjadi tidak stabil, berisiko mengeringkan kulit.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-059', 'ING-315', 'ING-316', 'Low', 'Extreme Occlusion', 'INFO: Menggabungkan Mineral Oil dan Petrolatum bisa sangat komedogenik bagi kulit berminyak, memicu jerawat kistik.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-061', 'ING-371', 'ING-227', 'Medium', 'Photosensitivity', 'PERINGATAN: Lavender Water dan Lemon Peel Oil mengandung komponen volatil yang memicu reaksi fototoksik di bawah sinar matahari.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-063', 'ING-078', 'ING-465', 'High', 'Mutual Cancellation', 'BAHAYA: Benzoyl Peroxide memecah turunan Retinoid (Retinyl Palmitate) menjadi tidak stabil.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-064', 'ING-011', 'ING-012', 'Medium', 'AHA Overload', 'PERINGATAN: Glycolic Acid dan Lactic Acid di rutinitas yang sama menyebabkan penipisan stratum corneum (over-exfoliation).', '2026-05-19 09:12:09.928125+00'),
  ('WARN-065', 'ING-011', 'ING-014', 'Medium', 'Exfoliant Overload', 'PERINGATAN: Menggabungkan AHA dan PHA bisa melemahkan fungsi pelindung alami kulit.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-066', 'ING-085', 'ING-252', 'Medium', 'Acidity vs Peptides', 'PERINGATAN: Ferulic Acid yang sangat asam dapat mendegradasi efektivitas peptida tembaga.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-067', 'ING-085', 'ING-455', 'Medium', 'Acidity vs Proteins', 'PERINGATAN: Ferulic Acid berpotensi mengubah bentuk struktur EGF, menurunkan efikasi perbaikan selnya.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-068', 'ING-187', 'ING-001', 'Medium', 'Clay & Acid Dryness', 'PERINGATAN: Masker Kaolin menyerap minyak. Jika langsung diikuti BHA, kulit akan kehilangan seluruh sebum alaminya.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-069', 'ING-188', 'ING-011', 'Medium', 'Clay & Acid Dryness', 'PERINGATAN: Bentonite dan Glycolic Acid berurutan dapat menyebabkan kulit terasa kaku dan tertarik (dehidrasi).', '2026-05-19 09:12:09.928125+00'),
  ('WARN-070', 'ING-068', 'ING-353', 'Low', 'Synthetic Antioxidant Load', 'INFO: Penggunaan BHT dan BHA (pengawet) berlebihan dari beberapa produk sekaligus dapat mensensitisasi kulit reaktif.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-071', 'ING-369', 'ING-002', 'Medium', 'Astringent vs Retinoid', 'PERINGATAN: Witch Hazel mengandung tannin yang mengeringkan. Dipadukan Retinol akan memicu kulit pecah-pecah.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-072', 'ING-369', 'ING-011', 'Medium', 'Astringent vs Acid', 'PERINGATAN: Witch Hazel dan Glycolic Acid adalah kombinasi sangat agresif yang mengikis kelembapan kulit.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-075', 'ING-075', 'ING-011', 'Medium', 'Deep Penetration Risk', 'PERINGATAN: Alpha-Arbutin menembus terlalu dalam jika skin barrier dilemahkan oleh Glycolic Acid, memicu iritasi.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-076', 'ING-245', 'ING-002', 'Medium', 'Brightening Clash', 'PERINGATAN: Undecylenoyl Phenylalanine dan Retinol bisa terlalu keras bagi melanosit kulit.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-077', 'ING-467', 'ING-011', 'Medium', 'Granactive & AHA', 'PERINGATAN: Granactive Retinol dan Glycolic Acid bersamaan berisiko merusak mantel asam pelindung kulit.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-078', 'ING-467', 'ING-001', 'Medium', 'Granactive & BHA', 'PERINGATAN: BHA membersihkan pori dalam, Granactive merangsang sel. Bersamaan, mereka memicu "purging" berlebihan.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-079', 'ING-468', 'ING-077', 'High', 'Dermatitis Risk', 'BAHAYA: Adapalene dan Azelaic Acid memicu reaksi peradangan parah jika kulit tidak dihidrasi dengan sangat baik.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-080', 'ING-469', 'ING-077', 'High', 'Dermatitis Risk', 'BAHAYA: Tretinoin dan Azelaic Acid murni dapat menyebabkan kulit mengelupas parah dan nyeri berdenyut.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-081', 'ING-004', 'ING-459', 'Medium', 'Peptide Inactivation', 'PERINGATAN: Ascorbic Acid murni berpotensi melemahkan efektivitas Palmitoyl Tetrapeptide-7.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-082', 'ING-004', 'ING-460', 'Medium', 'Peptide Inactivation', 'PERINGATAN: Ascorbic Acid dan Palmitoyl Tripeptide-1 sebaiknya tidak dilapiskan langsung karena perbedaan pH optimal.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-083', 'ING-004', 'ING-461', 'Medium', 'Peptide Inactivation', 'PERINGATAN: Vitamin C dapat mengurangi stabilitas Palmitoyl Tripeptide-38.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-084', 'ING-004', 'ING-462', 'Medium', 'Peptide Inactivation', 'PERINGATAN: Acetyl Tetrapeptide-5 (untuk mata) bisa mengiritasi jika terkena imbas asam dari Vitamin C.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-085', 'ING-004', 'ING-463', 'Medium', 'Peptide Inactivation', 'PERINGATAN: Acetyl Hexapeptide-1 dan Vitamin C murni memiliki kecocokan pH yang buruk.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-086', 'ING-004', 'ING-464', 'Medium', 'Peptide Inactivation', 'PERINGATAN: Nonapeptide-1 efektivitasnya terganggu oleh formulasi pH rendah dari Ascorbic Acid.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-087', 'ING-483', 'ING-193', 'Medium', 'Filter Degradation', 'PERINGATAN: Titanium Dioxide yang tidak di-coating dapat mempercepat degradasi Avobenzone di bawah sinar UV.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-088', 'ING-483', 'ING-192', 'Low', 'Formulation Conflict', 'INFO: Titanium Dioxide dan Ethylhexyl Salicylate harus diformulasikan presisi agar tidak menggumpal (pilling).', '2026-05-19 09:12:09.928125+00'),
  ('WARN-089', 'ING-189', 'ING-001', 'Medium', 'Over-cleansing', 'PERINGATAN: Charcoal Powder (karbon aktif) dan Salicylic Acid sangat mengikis kelembapan. Wajib pakai pelembap tebal.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-090', 'ING-315', 'ING-483', 'Low', 'Clogged Pores', 'INFO: Mineral Oil ditambah Titanium Dioxide (Sunscreen/Makeup) sangat komedogenik dan susah dibersihkan tanpa double cleansing.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-091', 'ING-316', 'ING-483', 'Low', 'Clogged Pores', 'INFO: Petrolatum dan physical UV filter bisa menyumbat pori jika tidak dibilas menggunakan oil cleanser.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-092', 'ING-173', 'ING-009', 'Low', 'Silicone Build-up', 'INFO: Melapiskan banyak produk dengan Cyclomethicone dan Dimethicone memicu "pilling" (produk menggumpal/daki).', '2026-05-19 09:12:09.928125+00'),
  ('WARN-093', 'ING-053', 'ING-054', 'Low', 'Silicone Build-up', 'INFO: Cyclopentasiloxane dan Cyclohexasiloxane berlebih menghalangi penyerapan skincare tahap selanjutnya.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-094', 'ING-227', 'ING-011', 'High', 'Acidic Citrus Burn', 'BAHAYA: Lemon Peel Oil mengandung furanocoumarins. Bersama Glycolic Acid di bawah matahari memicu Phytophotodermatitis.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-095', 'ING-226', 'ING-012', 'High', 'Acidic Citrus Burn', 'BAHAYA: Orange Peel Oil dan Lactic Acid melemahkan kulit terhadap radiasi UV, memicu flek hitam instan.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-096', 'ING-224', 'ING-002', 'Medium', 'Sensitization', 'PERINGATAN: Rosemary Oil meningkatkan sirkulasi darah, yang bisa membuat efek iritasi Retinol terasa lebih membakar.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-097', 'ING-225', 'ING-469', 'High', 'Sensitization', 'BAHAYA: Lavender Oil sangat reaktif jika diaplikasikan di atas kulit yang sedang dalam perawatan Tretinoin.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-098', 'ING-369', 'ING-469', 'High', 'Severe Dehydration', 'BAHAYA: Witch Hazel Water memicu dehidrasi ekstrem jika digunakan dalam regimen Tretinoin.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-099', 'ING-131', 'ING-344', 'Low', 'Preservative Interaction', 'INFO: Caprylyl Glycol dan DMDM Hydantoin aman, namun menumpuk banyak pengawet mensensitisasi kulit atopik.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-100', 'ING-468', 'ING-012', 'High', 'Exfoliant Burn', 'BAHAYA: Adapalene dan Lactic Acid (AHA) secara bersamaan berisiko tinggi memicu iritasi dan luka mikroskopis pada kulit.', '2026-05-19 09:12:09.928125+00'),
  ('WARN-101', 'ING-500', 'ING-011', 'High', 'Retinoid & Acid Clash', 'BAHAYA: Retinal (Retinaldehyde) dan Glycolic Acid (AHA) adalah bahan aktif yang sangat kuat. Menggabungkannya secara bersamaan berisiko tinggi merusak skin barrier, memicu iritasi hebat, kemerahan, dan pengelupasan ekstrim. Gunakan secara terpisah di malam yang berbeda.', '2026-06-02 02:14:59.000+00'),
  ('WARN-102', 'ING-500', 'ING-001', 'High', 'Severe Barrier Stripping', 'BAHAYA: Melapiskan Retinal dengan BHA (Salicylic Acid) dapat mengikis kelembapan alami kulit secara drastis, memicu dermatitis kontak dan iritasi parah. Sebaiknya gunakan BHA di pagi hari dan Retinal di malam hari.', '2026-06-02 02:14:59.000+00'),
  ('WARN-103', 'ING-500', 'ING-078', 'High', 'Ingredient Deactivation', 'BAHAYA: Benzoyl Peroxide akan mengoksidasi dan mendegradasi Retinal secara instan, membuat keduanya tidak efektif sekaligus memicu kulit menjadi sangat kering, mengelupas, dan meradang.', '2026-06-02 02:14:59.000+00'),
  ('WARN-104', 'ING-500', 'ING-004', 'High', 'Severe pH Imbalance', 'BAHAYA: Vitamin C murni (Ascorbic Acid) memerlukan pH rendah untuk menyerap, sedangkan Retinal bekerja optimal pada pH netral. Melapisinya bersamaan akan memicu iritasi hebat dan kemerahan parah pada kulit.', '2026-06-02 02:14:59.000+00'),
  ('WARN-105', 'ING-501', 'ING-002', 'Medium', 'Exfoliant & Retinol Clash', 'PERINGATAN: Succinic Acid memiliki sifat eksfoliasi dan sebum control ringan. Jika dilapiskan langsung dengan Retinol, dapat memicu sensitivitas ekstra bagi kulit reaktif atau pemula.', '2026-06-02 02:14:59.000+00'),
  ('WARN-106', 'ING-502', 'ING-011', 'Medium', 'Double Exfoliation Risk', 'PERINGATAN: Capryloyl Salicylic Acid (LHA) dan Glycolic Acid (AHA) bekerja mengelupas sel kulit mati. Melapisinya berisiko menyebabkan over-eksfoliasi, kulit menjadi tipis, perih, dan rentan berjerawat.', '2026-06-02 02:14:59.000+00'),
  ('WARN-107', 'ING-541', 'ING-002', 'High', 'Extreme Dryness Risk', 'BAHAYA: Menggabungkan Colloidal Sulfur dengan Retinol dapat memicu kekeringan ganda yang ekstrim dan merusak skin barrier, terutama bagi tipe kulit sensitif.', '2026-06-02 02:14:59.000+00'),
  ('WARN-108', 'ING-541', 'ING-500', 'High', 'Severe Retinoid & Sulfur Clash', 'BAHAYA: Melapiskan Retinal bersama dengan Colloidal Sulfur dapat menyebabkan iritasi parah, kemerahan bersisik, dan rasa terbakar pada kulit.', '2026-06-02 02:14:59.000+00'),
  ('WARN-109', 'ING-500', 'ING-012', 'High', 'Retinoid & AHA Clash', 'BAHAYA: Retinal dan Lactic Acid (AHA) secara bersamaan dapat mempercepat pergantian sel secara berlebihan, merusak pelindung kulit alami dan menyebabkan sensasi perih.', '2026-06-02 02:14:59.000+00'),
  ('WARN-110', 'ING-502', 'ING-001', 'Medium', 'Acid Layering Warning', 'PERINGATAN: LHA dan BHA sama-sama merupakan turunan asam yang larut dalam minyak untuk membersihkan pori. Menggunakan keduanya bersamaan dapat mengikis sebum alami secara berlebihan.', '2026-06-02 02:14:59.000+00'),
  ('WARN-111', 'ING-541', 'ING-001', 'Medium', 'Acne Treatment Drying', 'PERINGATAN: Salicylic Acid (BHA) dan Colloidal Sulfur keduanya adalah agen anti-jerawat yang sangat mengeringkan. Gunakan pelembap tebal jika terpaksa menggunakannya bersamaan.', '2026-06-02 02:14:59.000+00'),
  ('WARN-112', 'ING-503', 'ING-011', 'Low', 'Vitamin C Derivative Layering', 'INFO: Meskipun Tetrahexyldecyl Ascorbate (turunan Vitamin C) jauh lebih stabil dan ramah kulit dibanding Ascorbic Acid, melapisinya dengan Glycolic Acid berkonsentrasi tinggi tetap dapat menurunkan kenyamanan kulit sensitif.', '2026-06-02 02:14:59.000+00'),
  ('WARN-113', 'ING-500', 'ING-077', 'Medium', 'Active Retinoid Conflict', 'PERINGATAN: Retinal dan Azelaic Acid adalah kombinasi ampuh untuk mengatasi jerawat dan noda hitam, namun melapisinya secara bersamaan berisiko tinggi memicu kulit bersisik dan kering.', '2026-06-02 02:14:59.000+00'),
  ('WARN-114', 'ING-501', 'ING-500', 'Medium', 'Active Layering Conflict', 'PERINGATAN: Succinic Acid dan Retinal sebaiknya tidak digunakan bersamaan dalam satu langkah untuk menghindari risiko iritasi kulit.', '2026-06-02 02:14:59.000+00'),
  ('WARN-115', 'ING-500', 'ING-003', 'Low', 'Excellent Synergy', 'INFO: Niacinamide dan Retinal adalah kombinasi emas! Niacinamide memperkuat skin barrier dan mengurangi efek iritasi dari Retinal, sehingga aman dan sangat dianjurkan untuk anti-aging.', '2026-06-02 02:14:59.000+00') ON CONFLICT (rule_id) DO NOTHING;
